#!/usr/bin/env python3
"""Generate protocol constants from schema.json. --check verifies tracked outputs."""
import json, pathlib, sys
root=pathlib.Path(__file__).resolve().parent
schema=json.loads((root/'schema.json').read_text())
items=schema['constants']
outputs={
 'c/ks_timbre_contract.h':'/* Generated by generate.py; edit schema.json. */\n#pragma once\n'+''.join(f'#define KST_{k} {v}u\n' for k,v in items.items()),
 'sv/ks_timbre_contract_pkg.sv':'// Generated by generate.py; edit schema.json.\npackage ks_timbre_contract_pkg;\n'+''.join(f'    localparam integer KST_{k} = {v};\n' for k,v in items.items())+'endpackage\n',
 'python/ks_timbre_contract.py':'# Generated by generate.py; edit schema.json.\n'+''.join(f'{k} = {v}\n' for k,v in items.items())}
for name,content in outputs.items():
 p=root/'generated'/name
 if '--check' in sys.argv:
  if not p.exists() or p.read_text()!=content: raise SystemExit(f'stale generated file: {p}')
 else:
  p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
